import{_ as t,o as s,c as a,a6 as r}from"./chunks/framework.CCKCzdWs.js";const p=JSON.parse(`{"title":"CSS coverage","description":"The style sheet rules each Playwright test's pages matched, recorded from Chromium's CSS rule usage, so a change to a rule selects the tests that rendered it instead of the whole suite.","frontmatter":{"title":"CSS coverage","description":"The style sheet rules each Playwright test's pages matched, recorded from Chromium's CSS rule usage, so a change to a rule selects the tests that rendered it instead of the whole suite.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/css-coverage.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/css-coverage.html"}],["meta",{"property":"og:title","content":"CSS coverage | Piwi Dashboard"}],["meta",{"property":"og:description","content":"The style sheet rules each Playwright test's pages matched, recorded from Chromium's CSS rule usage, so a change to a rule selects the tests that rendered it instead of the whole suite."}]]},"headers":[],"relativePath":"features/css-coverage.md","filePath":"features/css-coverage.md","lastUpdated":1793399825000}`),o={name:"features/css-coverage.md"};function i(h,e,c,n,l,d){return s(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="css-coverage" tabindex="-1">CSS coverage <a class="header-anchor" href="#css-coverage" aria-label="Permalink to &quot;CSS coverage&quot;">​</a></h1><p>Each test records the rules of your style sheets its pages matched: a rule counts once an element on the page matched its selector. A change to a style sheet then selects the tests that rendered the rules it touched, where a style change used to run the whole suite. It sits beside <a href="./code-reach.html">code reach</a>, the scripts&#39; side, and <a href="./server-coverage.html">server coverage</a>.</p><h2 id="turn-it-on" tabindex="-1">Turn it on <a class="header-anchor" href="#turn-it-on" aria-label="Permalink to &quot;Turn it on&quot;">​</a></h2><p>Set <code>coverage.css: &#39;rules&#39;</code> in the reporter options, or <code>PIWI_COVERAGE_CSS=rules</code>, with the <a href="/guide/capture-fixtures.html">capture fixtures</a> in place. It is a choice of its own, independent of <code>coverage.browser</code>.</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reporter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;@piwitests/reporter&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, { coverage: { browser: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;functions&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, css: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;rules&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } }]],</span></span></code></pre></div><h2 id="what-it-records" tabindex="-1">What it records <a class="header-anchor" href="#what-it-records" aria-label="Permalink to &quot;What it records&quot;">​</a></h2><p>The fixtures start Chromium&#39;s CSS rule usage on each page the test has, in the same capture as code reach, and read it as each document is left and when the test ends. Each style sheet goes to its file:</p><ul><li>a sheet with a source map (Sass, Less, PostCSS, a <code>.vue</code> file&#39;s <code>&lt;style&gt;</code> with Vite&#39;s <code>css.devSourcemap</code>) counts in the map&#39;s sources;</li><li>a <code>&lt;style&gt;</code> element a Vite dev server injected counts in the file its <code>data-vite-dev-id</code> names, at its lines there, a component&#39;s <code>&lt;style&gt;</code> block included;</li><li>a sheet served as written (<code>/assets/app.css</code>) is the file at that path, found as <a href="./code-reach.html#what-it-records">code reach</a> finds a module.</li></ul><p>Without a source map, a sheet&#39;s lines are the file&#39;s only when each rule sits at the same line in the file: a preprocessor&#39;s output served without its map (Sass, PostCSS, Tailwind, an inlined <code>@import</code>) counts at file level, so a change to that file keeps every test that matched one of its rules.</p><p>A style rule counts from its selector to its closing brace, like a function. A grouping rule (<code>@media</code>, <code>@supports</code>, <code>@layer</code>, <code>@container</code>) counts its first line once a rule inside it matched. Every rule of each sheet, matched or not, goes with the run, for the file&#39;s ratio.</p><h2 id="where-it-is-used" tabindex="-1">Where it is used <a class="header-anchor" href="#where-it-is-used" aria-label="Permalink to &quot;Where it is used&quot;">​</a></h2><p>Wherever browser files are read: the execution page&#39;s coverage, a file&#39;s coverage page, the tests behind a line, <a href="./change-impact.html">test selection</a> (a changed rule selects the tests that matched it; a change outside every rule, at file level, the tests that matched any), and <a href="./uncovered-changes.html">uncovered changes</a>.</p><p>On the sample application, a change to its stylesheet selected 24 of its 32 tests by file, and 12 by line for a change to one rule, where it ran all 32 before.</p><h2 id="cost" tabindex="-1">Cost <a class="header-anchor" href="#cost" aria-label="Permalink to &quot;Cost&quot;">​</a></h2><p>The cost is Chromium&#39;s style recalculation, not the reads: about 10% more per test on the sample application, close to what function coverage costs there, and up to 57% on a page with 2,000 rules and frequent re-renders, where function coverage costs 4%. Turn it on where style changes are frequent, or in a scheduled run.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li><strong>Chromium only</strong>, like JavaScript coverage.</li><li><strong>A state the tests never reach reads as unused:</strong> a <code>:hover</code> never hovered, a breakpoint never rendered, a theme never set.</li><li><strong>Utility CSS</strong> (Tailwind) maps into the framework&#39;s own sheet under <code>node_modules</code>, which counts for nothing: the classes a test used are in the templates code reach already covers.</li><li><strong>CSS-in-JS and constructed sheets</strong> (<code>adoptedStyleSheets</code>) have no file.</li><li><strong>Production builds:</strong> Vite writes no source map for its CSS and minifies it to one line, so a built sheet maps to no source. Record CSS coverage against a dev server, or an application serving its CSS as written.</li><li>A <code>&lt;style&gt;</code> in a page&#39;s HTML counts only when the page&#39;s address names its file (<code>/index.html</code>).</li><li>A document replaced without <code>beforeunload</code> (<code>page.setContent</code>) loses the rules it matched: Chromium drops them with it.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./code-reach.html">Code reach</a>: the scripts each test ran</li><li><a href="./change-impact.html">Change impact</a>: the tests a change selects</li><li><a href="/reference/coverage-cost.html">Coverage cost</a>: what each mode costs</li></ul>',19)])])}const g=t(o,[["render",i]]);export{p as __pageData,g as default};
